select throws_ok($$select pg_temp.call('post_purchase_return',jsonb_set(pg_temp.purchase_return('number-return','bill','bill.line','0.1'),'{lines,0,quantity}','0.1'))$$,'22023',null,'return quantity rejects JSON numbers');
select throws_ok($$select pg_temp.call('post_purchase_return',pg_temp.purchase_return('wrong-line','bill','direct-bill.line','0.1'))$$,'22023','RETURN_SOURCE_LINE_INVALID','return source line must belong to selected scoped bill');
select throws_ok($$select pg_temp.call('post_purchase_return',pg_temp.purchase_return('no-reason','bill','bill.line','0.1')||'{"reason":" "}')$$,'22023','RETURN_INPUT_INVALID','return requires accountable reason');
