select is(pg_temp.call('post_purchase_return',pg_temp.purchase_return('purchase-return','bill','bill.line','0.15'),null,'purchase-return'),(select response from procurement_responses where name='purchase-return'),'return retry replays identical response');
select is((select original_amount::text from finance.open_items where source_id=pg_temp.fid('purchase-return')),'-16.670000','partial billed return creates exact supplier credit');
select is((select on_hand_quantity::text from inventory.stock_balances where tenant_id=pg_temp.fid('tenant')),'4.800000','purchase return issues frozen twelve-unit stock quantity exactly once');
