select throws_ok($$select pg_temp.call('post_purchase_return',pg_temp.purchase_return('second-excess','bill','bill.line','0.31'))$$,'22023','RETURN_QUANTITY_UNAVAILABLE','posted return reduces subsequent eligibility');
