select is((select stock_movement_id from procurement.purchase_returns where id=pg_temp.fid('service-return')),null::uuid,'nonstock debit does not create stock');
select pg_temp.call('post_purchase_return',pg_temp.purchase_return('service-rest','direct-bill','direct-bill.line','1'));
select is((select sum(total)::text from procurement.purchase_returns where source_id=pg_temp.fid('direct-bill')),'295.300000','complete partial returns exhaust original bill total without a lost cent');
select is((select sum(base_credit)::text from finance.journal_lines where account_id=pg_temp.fid('input-tax-account') and journal_entry_id in(select journal_entry_id from procurement.purchase_returns where source_id=pg_temp.fid('direct-bill'))),'45.050000','complete debit notes reverse original input tax exactly');
