create function pg_temp.trace(n text) returns jsonb language sql as $$select api.receipt_trace_detail(pg_temp.fid('tenant'),pg_temp.fid('entity'),pg_temp.fid('branch'),pg_temp.fid(n||'.ml'))$$;
