select throws_ok($$select pg_temp.call('bank_reconciliation_command',pg_temp.bank_import('bad')||'{"lines":[]}',0)$$,'22023','BANK_STATEMENT_INVALID','empty import rejected');
select throws_ok($$select pg_temp.call('bank_reconciliation_command',jsonb_set(pg_temp.bank_import('bad'),'{lines,0,reference}','"bank.statement"'),0)$$,'23505',null,'overlapping reference rejected');
