select is((select sum(l.base_debit-l.base_credit) from finance.journal_lines l where l.journal_entry_id=(select adjustment_journal_id from finance.bank_matches where id=pg_temp.fid('bank.adjust'))),0::numeric,'tolerance adjustment journal balances');
select is((select base_credit from finance.journal_lines where journal_entry_id=(select adjustment_journal_id from finance.bank_matches where id=pg_temp.fid('bank.adjust')) and account_id=pg_temp.fid('bank.gl')),0.5::numeric,'adjustment reconciles exact bank amount');
