select is(pg_temp.call('generate_close_control_review',pg_temp.close_payload('close.main'),0,'close.main'),(select response from procurement_responses where name='close.main'),'exact replay returns the original frozen review');
select throws_ok($$select pg_temp.call('generate_close_control_review',pg_temp.close_payload('close.main')||'{"as_of":"2026-09-24"}',0,'close.main')$$,'22023',null,'changed replay cutoff rejected');
select throws_ok($$select pg_temp.call('generate_close_control_review',pg_temp.close_payload('close.version'),1)$$,'40001',null,'creation expected version must be zero');
select throws_ok($$select pg_temp.call('generate_close_control_review',pg_temp.close_payload('close.future')||'{"as_of":"2099-09-25"}',0)$$,'22023',null,'future cutoff fails before save');
