select throws_ok($$select pg_temp.lex_preview(jsonb_set(pg_temp.lex_payload(),'{receipts,0,receipt_line_id}',to_jsonb(pg_temp.fid('lex.foreign'))))$$,'22023','LANDED_EXTENSION_RECEIPT_INVALID','foreign or absent receipt rejected');
select throws_ok($$select pg_temp.lex_preview(jsonb_set(pg_temp.lex_payload(),'{receipts,1,receipt_line_id}',to_jsonb(pg_temp.lex_line('lex.receipt.a'))))$$,'22023','LANDED_EXTENSION_RECEIPTS_INVALID','duplicate receipt cannot inflate basis');
